import {getFillRegions} from './fill-regions.js';
export function validFills(state){if(state.fills===undefined)return true;if(!Array.isArray(state.fills)||state.fills.length>200)return false;const ids=new Set(getFillRegions(state.pattern).map(r=>r.id)),seen=new Set();return state.fills.every(f=>f&&ids.has(f.region)&&!seen.has(f.region)&&seen.add(f.region)&&/^#[0-9a-f]{6}$/i.test(f.color)&&typeof f.rainbow==='boolean')}
export function drawFills(ctx,state){for(const fill of state.fills||[]){const region=getFillRegions(state.pattern).find(r=>r.id===fill.region);if(!region)continue;ctx.save();ctx.globalCompositeOperation='source-over';ctx.globalAlpha=1;if(fill.rainbow){const gradient=ctx.createLinearGradient(0,0,1000,900);['#ef476f','#ffd166','#06d6a0','#118ab2','#9b5de5'].forEach((color,i)=>gradient.addColorStop(i/4,color));ctx.fillStyle=gradient}else ctx.fillStyle=fill.color;for(const [y,x1,x2]of region.spans)ctx.fillRect(x1,y,x2-x1,1);ctx.restore()}}
